  for(let dy=-radius;dy<=radius;dy++){
    const y=ty+dy;if(y<0||y>=height)continue;
    for(let dx=-radius;dx<=radius;dx++){
      const x=tx+dx;if(x<0||x>=width||dx*dx+dy*dy>radius*radius)continue;
