    let x=0;
    while(x<maskW){
      while(x<maskW&&!mask[y*maskW+x])x++;
      const start=x;
      while(x<maskW&&mask[y*maskW+x])x++;
      if(x>start)rows.push({y:y+top,left:start+left,right:x-1+left});
    }
  }
  return {left,top,right,bottom,area,rows};
